package com.akira.one;
import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AlertDialog;import androidx.appcompat.app.AppCompatActivity;import androidx.recyclerview.widget.*;import java.util.*;
public class FavoritesActivity extends BaseActivity{private final List<ContentItem> items=new ArrayList<>();private ContentAdapter adapter;protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_favorites);RecyclerView rv=findViewById(R.id.favoritesRecycler);rv.setLayoutManager(new GridLayoutManager(this,3));adapter=new ContentAdapter(items,new ContentAdapter.Listener(){public void onClick(ContentItem i){ContentNavigator.open(FavoritesActivity.this,i);}public void onLongClick(ContentItem i){new AlertDialog.Builder(FavoritesActivity.this).setTitle(i.name).setMessage("Remover dos favoritos?").setPositiveButton("Remover",(d,w)->{Prefs.toggleFavorite(FavoritesActivity.this,i);load();}).setNegativeButton("Cancelar",null).show();}});rv.setAdapter(adapter);}protected void onResume(){super.onResume();load();}private void load(){items.clear();items.addAll(Prefs.favorites(this));adapter.notifyDataSetChanged();((TextView)findViewById(R.id.favoritesStatus)).setText(items.isEmpty()?"Nenhum favorito ainda. Segure OK em um item para adicionar.":items.size()+" favorito(s)");}}
